type IssueLike = Pick<
  AccessibilityIssue,
  "wcagCriterion" | "severity" | "category"
> & { source?: string; occurrenceCount?: number };

function deriveTeam(issue: IssueLike): string {
  const c = issue.wcagCriterion;
  if (["1.1.1", "1.2.1", "1.2.2", "1.2.5"].includes(c)) return "Content";
  if (["1.4.3", "1.4.11", "1.3.3"].includes(c)) return "Designer";
  if (issue.source === "pdf-analyzer" || issue.category === "pdf")
    return "PDF Team";
  if (["1.3.1", "4.1.2", "4.1.3"].includes(c)) return "Design System";
  if (["3.3.1", "3.3.2", "3.3.3"].includes(c)) return "Frontend Dev";
  if (issue.source === "journey-test") return "QA";
  return "Frontend Dev";
}
function deriveEffort(issue: IssueLike): string {
  // For grouped issues with many instances, bump effort estimate
  if ((issue.occurrenceCount ?? 1) > 10) return "1 Sprint";
  return (
    (
      {
        critical: "1 Sprint",
        high: "Half-day",
        medium: "1 hour",
        low: "Quick Win",
      } as Record<string, string>
    )[issue.severity] || "1 hour"
  );
}

