// Shared running header/footer applied to every body page via didDrawPage.
// `pageNoProvider` lets us supply the current page index at draw time.
function makeRunningHeaderFooter(
  doc: jsPDF,
  pw: number,
  ph: number,
  label: string,
) {
  return () => {
    const pageCount = doc.getNumberOfPages();
    const pageNo = doc.getCurrentPageInfo().pageNumber;
    // drawDocHeader(doc, pw, ph, false);
    drawDocFooter(doc, pw, ph, pageNo, pageCount, label);
  };
}

