type MgmtResponseHost =
  | AccessibilityIssue
  | DarkPatternFinding
  | { managementResponse?: any; pageUrl?: string; title?: string }
  | any;

function getManagementResponse(host: MgmtResponseHost): any | undefined {
  return (host as any)?.managementResponse;
}

function drawPageBorder(doc: jsPDF, pw: number, ph: number) {
  // 1. Set explicit padding dimensions for each independent edge (in mm)
  const padLeft = 19; // Distance from absolute left edge
  const padTop = 11; // Distance from absolute top edge
  const padRight = 20; // Distance from absolute right edge
  const padBottom = 20; // Distance from absolute bottom edge

  // 2. Compute the exact bounding line endpoints across the canvas space
  const startX = padLeft;
  const endX = pw - padRight;
  const startY = padTop;
  const endY = ph - padBottom;

  // 3. Set your border style properties
  doc.setDrawColor(235, 235, 235);
  doc.setLineWidth(0.3);

  // 4. Draw the four boundaries independently to assemble the frame
  doc.line(startX, startY, endX, startY); // Top Line
  doc.line(endX, startY, endX, endY); // Right Line
  doc.line(startX, endY, endX, endY); // Bottom Line
  doc.line(startX, startY, startX, endY); // Left Line
}

